static void pack_a(const float *A, int n, int i0, int mc, int p0, int kc, float *restrict ap)
{
    for (int ir = 0; ir < mc; ir += MR) {
        int mr = mc - ir < MR ? mc - ir : MR;
        for (int r = 0; r < MR; r++) {
            if (r < mr) {
                const float *src = A + (size_t)(i0 + ir + r) * n + p0;
                for (int k = 0; k < kc; k++) ap[k * MR + r] = src[k];
            } else {
                for (int k = 0; k < kc; k++) ap[k * MR + r] = 0.0f;
            }
        }
        ap += (size_t)MR * kc;
    }
