void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npan = (n + NR - 1) / NR;
    size_t bsz = (size_t)n * npan * NR * sizeof(float);
    bsz = (bsz + 63) & ~(size_t)63;
    float *Bp = (float *)aligned_alloc(64, bsz);

    int nib = (n + MC - 1) / MC;
    int njb = (n + NC - 1) / NC;
    int nkb = (n + KC - 1) / KC;

    #pragma omp parallel
    {
        float *ap = (float *)aligned_alloc(64, (size_t)MC * KC * sizeof(float));

        /* Pack B: for each k-block p0, panels of kc x NR, zero padded. */
        #pragma omp for collapse(2) schedule(static)
        for (int kb = 0; kb < nkb; kb++) {
            for (int jp = 0; jp < npan; jp++) {
                int p0 = kb * KC;
                int kc = n - p0 < KC ? n - p0 : KC;
                int j0 = jp * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                float *dst = Bp + (size_t)p0 * npan * NR + (size_t)jp * kc * NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(p0 + k) * n + j0;
                    float *d = dst + k * NR;
                    int j = 0;
                    for (; j < nr; j++) d[j] = src[j];
                    for (; j < NR; j++) d[j] = 0.0f;
                }
            }
        }

        #pragma omp for collapse(2) schedule(dynamic, 1)
        for (int ib = 0; ib < nib; ib++) {
            for (int jb = 0; jb < njb; jb++) {
                int i0 = ib * MC;
                int mc = n - i0 < MC ? n - i0 : MC;
                int j0 = jb * NC;
                int nc = n - j0 < NC ? n - j0 : NC;
                int jp0 = j0 / NR;
                int jp1 = (j0 + nc + NR - 1) / NR;
                for (int kb = 0; kb < nkb; kb++) {
                    int p0 = kb * KC;
                    int kc = n - p0 < KC ? n - p0 : KC;
                    pack_a(A, n, i0, mc, p0, kc, ap);
                    const float *bblk = Bp + (size_t)p0 * npan * NR;
                    for (int jp = jp0; jp < jp1; jp++) {
                        int jj = jp * NR;
                        int nr = n - jj < NR ? n - jj : NR;
                        const float *bp = bblk + (size_t)jp * kc * NR;
                        for (int ir = 0; ir < mc; ir += MR) {
                            int mr = mc - ir < MR ? mc - ir : MR;
                            kernel(kc, ap + (size_t)ir * kc, bp,
                                   C + (size_t)(i0 + ir) * n + jj, n,
                                   mr, nr, kb == 0);
                        }
                    }
                }
            }
        }
        free(ap);
    }
    free(Bp);
