static void pack_a_panel(const float *A, int n, int row0, int p0, int kc,
                         float *restrict dst)
{
    int mr = n - row0 < MR ? n - row0 : MR;
    if (mr == MR) {
        const float *s[MR];
        for (int r = 0; r < MR; r++)
            s[r] = A + (size_t)(row0 + r) * n + p0;
