void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int nkb = (n + KCMAX - 1) / KCMAX;
    int kcb = (n + nkb - 1) / nkb;
    kcb = (kcb + 7) & ~7;
    nkb = (n + kcb - 1) / kcb;

    int npB = (n + NR - 1) / NR;
    float *Bp = grow(&gB, &capB, (size_t)npB * NR * n);

    int nth = omp_get_max_threads();
    int nib = (n + MC - 1) / MC;
    int njb = (4 * nth + nib - 1) / nib;
    if (njb < 1) njb = 1;
    int ppc = (npB + njb - 1) / njb;
    if (ppc > 32) ppc = 32;
    if (ppc < 4) ppc = 4;
    if (ppc > npB) ppc = npB;
    njb = (npB + ppc - 1) / ppc;
    int ntasks = nib * njb;

