    if (ppc > PPCMAX) ppc = PPCMAX;
    if (ppc < PPCMIN) ppc = PPCMIN;
    if (ppc > npB) ppc = npB;
    njb = (npB + ppc - 1) / ppc;
    int ntasks = nib * njb;

    #pragma omp parallel
    {
        /* Zero-padded copy of a partial MR-row strip of A (row edge only). */
        float ebuf[MR * KCMAX] __attribute__((aligned(64)));

        #pragma omp for collapse(2) schedule(static)
        for (int kb = 0; kb < nkb; kb++) {
            for (int jp = 0; jp < npB; jp++) {
